SELECT rc.*, ex.score_visible FROM el_exam_record rc INNER JOIN el_exam ex ON rc.exam_id=ex.id WHERE user_id=#{query.userId}

    
        AND ex.title LIKE CONCAT('%', #{query.title}, '%')
    
    
        AND rc.passed=#{query.passed}
    

ORDER BY rc.id DESC

SELECT rc.* FROM el_exam_record rc INNER JOIN el_sys_user uc ON rc.user_id=uc.id INNER JOIN el_exam ee ON ee.id=rc.exam_id

    
        
            AND rc.exam_id=#{query.examId}
        
        
            AND (uc.real_name LIKE CONCAT('%', #{query.userName}, '%') OR uc.user_name LIKE CONCAT('%',
            #{query.userName}, '%'))
        
        
            AND rc.passed=#{query.passed}
        
        
            AND rc.user_id=#{query.userId}
        
        
            AND uc.dept_code=#{query.deptCode}
        
        
            AND uc.dept_code IN
            
                #{dc}
            
        
        
            AND rc.max_score >= #{query.scoreMin}
        
        
            AND rc.max_score <= #{query.scoreMax}
        
    

ORDER BY rc.id DESC

SELECT rc.id, rc.user_id, rc.exam_id, rc.paper_id, rc.try_count, rc.max_score, rc.last_score, rc.passed,
       uc.real_name AS realName, uc.dept_code AS deptCode, dp.dept_name AS deptName,
       ee.title AS examTitle, rc.create_time AS createTime
FROM el_exam_record rc
         INNER JOIN el_sys_user uc ON rc.user_id = uc.id
         LEFT JOIN el_sys_depart dp ON uc.dept_code = dp.dept_code
         INNER JOIN el_exam ee ON ee.id = rc.exam_id

    
        
            AND rc.exam_id=#{query.examId}
        
        
            AND (uc.real_name LIKE CONCAT('%', #{query.userName}, '%') OR uc.user_name LIKE CONCAT('%',
            #{query.userName}, '%'))
        
        
            AND rc.passed=#{query.passed}
        
        
            AND rc.user_id=#{query.userId}
        
        
            AND uc.dept_code=#{query.deptCode}
        
        
            AND uc.dept_code IN
            
                #{dc}
            
        
        
            AND rc.max_score >= #{query.scoreMin}
        
        
            AND rc.max_score <= #{query.scoreMax}
        
    

ORDER BY rc.create_time DESC
